def chunk_words(text, size, overlap):
    if overlap < 0 or overlap >= size:
        raise ValueError('overlap must be >= 0 and < size')
    words = text.split()
    chunks = []
    step = size - overlap
    i = 0
    while i < len(words):
        chunks.append(' '.join(words[i:i + size]))
        if i + size >= len(words):
            break
        i += step
    return chunks

