def split_sections(md, source):
    title = source
    for line in md.splitlines():
        if line.startswith('# '):
            title = line[2:].strip()
            break
    out, heading, body = [], None, []
    def flush():
        if heading is not None:
            out.append({'id': f'{source}#{len(out)}', 'section': f'{title} > {heading}', 'text': '\n'.join(body).strip()})
    for line in md.splitlines():
        if line.startswith('## '):
            flush()
            heading, body = line[3:].strip(), []
        elif heading is not None:
            body.append(line)
    flush()
    return out

def _norm(s):
    return ' '.join(s.lower().split())

def hit_rate(retrieved, answers):
    if not answers:
        return 0.0
    hits = 0
    for chunks, ans in zip(retrieved, answers):
        a = _norm(ans)
        if any(a in _norm(c) for c in chunks):
            hits += 1
    return round(hits / len(answers), 2)
